const STORE_ID = '{{STORE_ID}}';
const ZERO_DEC = new Set(['clp','jpy','krw','vnd','pyg','xaf','xof','ugx','rwf','kmf','djf','gnf','mga','vuv']);
const ESTADO = { warning_needs_response: 'needs_response', needs_response: 'needs_response', warning_under_review: 'under_review', under_review: 'under_review', won: 'won', lost: 'lost', charge_refunded: 'closed', warning_closed: 'closed' };
const salida = [];
for (const item of $input.all()) {
  const lista = item.json.data || [];
  for (const d of lista) {
    const charge = (d.charge && typeof d.charge === 'object') ? d.charge : {};
    const md = charge.metadata || {};
    let orden = md.order_number || md.order_id || md.order_name || null;
    if (!orden) {
      const txt = String(charge.description || '');
      const m = txt.match(/#([A-Z]{0,3}\d{4,6})/i);
      if (m) orden = m[1];
    }
    if (orden) orden = String(orden).replace('#','').trim();
    const cur = String(d.currency || '').toLowerCase();
    const monto = ZERO_DEC.has(cur) ? d.amount : (d.amount / 100);
    const bd = charge.billing_details || {};
    salida.push({ json: {
      pasarela: 'stripe',
      dispute_id: d.id,
      store_id: STORE_ID,
      order_number: orden,
      cargo_id: (typeof d.charge === 'string') ? d.charge : (charge.id || null),
      email_clienta: bd.email || charge.receipt_email || null,
      monto: monto,
      moneda: cur,
      motivo: d.reason || null,
      estado: ESTADO[d.status] || 'needs_response',
      fecha_apertura: d.created ? new Date(d.created * 1000).toISOString() : null,
      fecha_limite: (d.evidence_details && d.evidence_details.due_by) ? new Date(d.evidence_details.due_by * 1000).toISOString() : null,
      raw: d
    }});
  }
}
return salida;
